-- Conversation module test: replays the chat events the bridge produces for
-- recorded Claude and Codex turns (agent/tests/fixtures, generated by the
-- bridge's npm test). Runs in Aseprite batch mode:
--   aseprite -b --script-param ext=<agent/extension> --script-param fixtures=<agent/tests/fixtures> \
--     --script agent/tests/conversation_test.lua

local Conversation = dofile(app.fs.joinPath(app.params.ext, "conversation.lua"))

local failures = 0
local function check(name, cond, detail)
  if cond then print("PASS " .. name)
  else failures = failures + 1; print("FAIL " .. name .. (detail and (": " .. tostring(detail)) or "")) end
end

local function readEvents(name)
  local f = assert(io.open(app.fs.joinPath(app.params.fixtures, name)))
  local events = json.decode(f:read("a"))
  f:close()
  return events
end

-- A clock the test advances by hand.
local t = 1000
local clock = function() return t end

for _, provider in ipairs{ "claude", "codex" } do
  local c = Conversation.new{ clock = clock }
  c:send("Draw a red pixel", provider)
  check(provider .. ": busy after send", c:isBusy())
  local e = c:entries()
  check(provider .. ": user + header", e[1].kind == "user" and e[2].kind == "header")

  local ended = false
  for _, ev in ipairs(readEvents("chat-events-" .. provider .. ".json")) do
    t = t + 2
    local r = c:apply(ev)
    if r.turnEnded then ended = true end
  end
  check(provider .. ": turn ended on done", ended and not c:isBusy())
  check(provider .. ": conversation id kept", c:conversationId(provider) ~= nil)

  local tools, ok, texts = 0, 0, 0
  for _, x in ipairs(c:entries()) do
    if x.kind == "tool" then
      tools = tools + 1
      if x.status == "ok" then ok = ok + 1 end
    elseif x.kind == "text" then texts = texts + 1 end
  end
  check(provider .. ": every tool resolved", tools > 0 and ok == tools, ok .. "/" .. tools)
  check(provider .. ": reply recorded", texts > 0)
  local last = c:entries()[#c:entries()]
  check(provider .. ": worked for N s", last.kind == "worked" and last.secs > 0, last.kind)
end

-- Timing, errors and reset, with a fresh conversation.
do
  local c = Conversation.new{ clock = clock }
  t = 0
  c:send("hi", "claude")
  t = 3
  c:apply{ type = "thinking", text = "plan" }
  local thought = c:entries()[3]
  check("thought timed from the previous step", thought.kind == "thought" and thought.secs == 3, thought.secs)
  check("status events don't add entries", c:apply{ type = "status", text = "working" }.status == "working" and #c:entries() == 3)
  c:apply{ type = "tool_result", id = "unknown", ok = true }
  check("unknown tool result is ignored", #c:entries() == 3)
  t = 10
  local r = c:apply{ type = "error", text = "quota" }
  local n = #c:entries()
  check("error ends the turn", r.turnEnded and not c:isBusy() and c:entries()[n].kind == "worked" and c:entries()[n - 1].kind == "error")

  c:send("again", "codex")
  c:fail("bridge down")
  check("fail ends the turn", not c:isBusy() and c:entries()[#c:entries()].kind == "worked")

  c:apply{ type = "session", provider = "codex", sessionId = "th1" }
  c:reset()
  check("reset clears entries and ids", #c:entries() == 0 and c:conversationId("codex") == nil)
end

-- The turn's last check becomes a badge on "Worked for" (#29).
do
  local c = Conversation.new{ clock = clock }
  c:send("draw", "claude")
  c:apply{ type = "tool", id = "c1", tool = "Check pixel art", name = "check", kind = "read" }
  c:apply{ type = "tool_result", id = "c1", name = "check", ok = true, detail = "Check: 0 errors, 2 warnings (1 layers, 1 frames)" }
  c:apply{ type = "done" }
  local w = c:entries()[#c:entries()]
  check("check badge recorded", w.kind == "worked" and w.check and w.check.errors == 0 and w.check.warnings == 2)
  c:send("again", "claude")
  c:apply{ type = "done" }
  check("no check, no badge", c:entries()[#c:entries()].check == nil)
end

print(failures == 0 and "ALL PASSED" or (failures .. " FAILED"))
